import{_ as e,o as t,c as o,a5 as i}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"HJ107 求解立方根","description":"中等 通过率：26.70% 时间限制：1秒 空间限制：32M 知识点 基础数学 二分 描述 计算一个浮点数的立方根，不使用库函数。 保留一位小数。 数据范围：∣���∣≤20 ∣ val ∣≤20 输入描述： 待求解参数，为double类型（一个实数） 输出描述： 输出参数的立方。","frontmatter":{"title":"HJ107 求解立方根","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：26.70% 时间限制：1秒 空间限制：32M 知识点 基础数学 二分 描述 计算一个浮点数的立方根，不使用库函数。 保留一位小数。 数据范围：∣���∣≤20 ∣ val ∣≤20 输入描述： 待求解参数，为double类型（一个实数） 输出描述： 输出参数的立方。","sidebarWeight":104,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/特定算法/HJ107 求解立方根.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/特定算法/HJ107 求解立方根.md","filePath":"posts/前端面试与实战/03-算法训练/特定算法/HJ107 求解立方根.md"}'),l={name:"posts/前端面试与实战/03-算法训练/特定算法/HJ107 求解立方根.md"};function r(s,a,n,p,h,d){return t(),o("div",null,[...a[0]||(a[0]=[i('<div><h1 id="hj107-求解立方根" tabindex="-1">HJ107 求解立方根 <a class="header-anchor" href="#hj107-求解立方根" aria-label="Permalink to &quot;HJ107 求解立方根&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ107 求解立方根”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：26.70% 时间限制：1秒 空间限制：32M 知识点==基础数学====二分== <strong>描述</strong> 计算一个浮点数的立方根，不使用库函数。 保留一位小数。</p></blockquote><p>数据范围：∣���∣≤20 ∣<em>val</em>∣≤20 <strong>输入描述：</strong> 待求解参数，为double类型（一个实数） <strong>输出描述：</strong> 输出参数的立方根。保留一位小数。 <strong>示例1</strong> 输入： 19.9 ==复制== 输出： 2.7 ==复制== <strong>示例2</strong> 输入： 2.7 ==复制== 输出： 1.4</p><p>牛顿迭代法 while True: try: a = float(input().strip()) # 获取输入的实数a e = 0.0001 # 设定一个精度值 t = a # 初始化立方根t的值为输入的值a while abs(t<em>t</em>t - a) &gt; e: # 差值没有达到精度，便一直更新立方根</p><h1 id="x-i-1-x-i-f-xi-f-xi" tabindex="-1">x(i+1) = x(i) - f(xi)/f&#39;(xi) <a class="header-anchor" href="#x-i-1-x-i-f-xi-f-xi" aria-label="Permalink to &quot;x(i+1) = x(i) - f(xi)/f&#39;(xi)&quot;">​</a></h1><h1 id="更新后的x-原x-原x的立方-a-f-原x-导数" tabindex="-1">更新后的x = 原x - (原x的立方-a)/f(原x)导数 <a class="header-anchor" href="#更新后的x-原x-原x的立方-a-f-原x-导数" aria-label="Permalink to &quot;更新后的x = 原x - (原x的立方-a)/f(原x)导数&quot;">​</a></h1><p>t = t - (t<em>t</em>t - a) * 1.0 / (3 * t*t) print(&quot;%.1f&quot; % t) # 当精度达到要求时，此时的立方根t便为输入实数的立方根解 except: break</p><p>二分法 while True: try:</p><h1 id="输入待求立方根的数" tabindex="-1">输入待求立方根的数 <a class="header-anchor" href="#输入待求立方根的数" aria-label="Permalink to &quot;输入待求立方根的数&quot;">​</a></h1><p>a = float(input().strip())</p><h1 id="设置精度值-用于判断当前的解是否足够接近真实立方根" tabindex="-1">设置精度值，用于判断当前的解是否足够接近真实立方根 <a class="header-anchor" href="#设置精度值-用于判断当前的解是否足够接近真实立方根" aria-label="Permalink to &quot;设置精度值，用于判断当前的解是否足够接近真实立方根&quot;">​</a></h1><p>epsilon = 0.0001</p><h1 id="设置查找的初始范围。如果a是负数-查找范围是-a-0-如果a是正数或0-查找范围是-0-a-或-1-a-如果a大于1" tabindex="-1">设置查找的初始范围。如果a是负数，查找范围是[a, 0]；如果a是正数或0，查找范围是[0, a]或[1, a]（如果a大于1） <a class="header-anchor" href="#设置查找的初始范围。如果a是负数-查找范围是-a-0-如果a是正数或0-查找范围是-0-a-或-1-a-如果a大于1" aria-label="Permalink to &quot;设置查找的初始范围。如果a是负数，查找范围是[a, 0]；如果a是正数或0，查找范围是[0, a]或[1, a]（如果a大于1）&quot;">​</a></h1><p>low = min(-1.0, a) high = max(1.0, a)</p><h1 id="计算中间值" tabindex="-1">计算中间值 <a class="header-anchor" href="#计算中间值" aria-label="Permalink to &quot;计算中间值&quot;">​</a></h1><p>ans = (low + high) / 2</p><h1 id="当当前解的立方与目标值a的差的绝对值大于epsilon时-继续查找" tabindex="-1">当当前解的立方与目标值a的差的绝对值大于epsilon时，继续查找 <a class="header-anchor" href="#当当前解的立方与目标值a的差的绝对值大于epsilon时-继续查找" aria-label="Permalink to &quot;当当前解的立方与目标值a的差的绝对值大于epsilon时，继续查找&quot;">​</a></h1><p>while abs(ans<strong>3 - a) &gt;= epsilon: if ans</strong>3 &lt; a: # 如果中间值的立方小于a，说明真实立方根在右侧，更新low为当前中间值 low = ans else: # 否则，真实立方根在左侧，更新high为当前中间值 high = ans</p><h1 id="重新计算中间值" tabindex="-1">重新计算中间值 <a class="header-anchor" href="#重新计算中间值" aria-label="Permalink to &quot;重新计算中间值&quot;">​</a></h1><p>ans = (low + high) / 2.0</p><h1 id="输出结果-保留一位小数" tabindex="-1">输出结果，保留一位小数 <a class="header-anchor" href="#输出结果-保留一位小数" aria-label="Permalink to &quot;输出结果，保留一位小数&quot;">​</a></h1><p>print(&#39;%.1f&#39; % ans) except EOFError: # 捕获输入结束的信号 break # 结束循环</p><p>在求解立方根（或其他类似数学问题）时，精度值（epsilon）的确定往往依赖于具体的应用场景和对结果精度的需求。精度值epsilon表示我们能接受的最大误差范围，它影响着算法的终止条件和最终结果的准确度。选择合适的epsilon是在算法的效率和结果精度之间寻找平衡的过程。</p><p>以下是确定epsilon的一些考虑因素：</p><ol><li><p>**应用需求：**首先需要考虑的是应用对精度的要求。不同的问题可能对结果的精度有不同的要求。例如，工程计算可能需要非常高的精度，而某些快速估计可能对精度的要求相对宽松。</p></li><li><p>**数值范围：**被求立方根的数的大小也会影响精度值的选择。对于非常大或非常小的数，可能需要调整epsilon的值以获得准确的结果。</p></li><li><p>**计算资源：**更小的epsilon值意味着更高的精度，但同时可能会导致算法需要更多的迭代次数，从而消耗更多的计算资源。在有限的计算资源下，需要在计算时间和精度之间做出权衡。</p></li><li><p>**数值稳定性：**在某些情况下，过小的epsilon可能会导致数值计算中的稳定性问题，从而影响结果的可靠性。</p></li></ol><p>在实际应用中，epsilon的值通常是根据经验选择的。一个常用的起点是<code>0.0001</code>或<code>0.001</code>，然后根据计算结果的准确性和算法的执行时间进行调整。如果需要非常高的精度，可以进一步减小epsilon；如果计算资源有限，或者对精度的需求不是非常高，可以适当增大epsilon。</p><p>在实际编程实践中，选择epsilon时还需要考虑到浮点数计算的精度限制，避免因为浮点数表示的精度问题而导致的死循环或是无法达到预期的精度。</p></div>',1)])])}const f=e(l,[["render",r]]);export{c as __pageData,f as default};
